// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function testFuzz_property(uint256 _am, uint256 _deposit, uint256 _minSum) public {
        // Keep the fuzzed domain wide but admissible: only require enough deposited balance
        // to attempt a collect, and cap amounts to avoid uint256 arithmetic overflow confusion.
        vm.assume(_am <= _deposit);
        vm.assume(_deposit < type(uint128).max);
        vm.assume(_minSum <= _deposit);

        // Deploy a LogFile instance and configure c so Collect/Deposit do not revert.
        LogFile log = new LogFile();
        c.SetMinSum(_minSum);
        c.SetLogFile(address(log));
        c.Initialized();

        // Fund a fuzzed actor and deposit into the reference contract.
        address actor = address(0xBEEF);
        // Use a prank to deposit from the actor (receive() calls Deposit internally).
        vm.deal(actor, _deposit);
        vm.prank(actor);
        (bool okDeposit, ) = address(c).call{value: _deposit}("");
        require(okDeposit, "deposit failed");

        uint256 balBefore = c.balances(actor);
        // The reference's Collect should succeed and reduce the actor's recorded balance by _am.
        vm.prank(actor);
        try c.Collect(_am) {
            uint256 balAfter = c.balances(actor);
            // General rule: successful collect reduces the actor's balance by exactly _am.
            assertTrue(balAfter == balBefore - _am);
        } catch {
            // If Collect reverts, the balance must remain unchanged.
            assertTrue(c.balances(actor) == balBefore);
        }
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
